 "content": "def transform(grid):
    """Count T tetrominoes by orientation and render their orientation signature."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    seen = set()
    counts = {"up": 0, "down": 0, "left": 0, "right": 0}
    for start in cells:
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        comp = {start}
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and q not in seen:
                    seen.add(q); comp.add(q); stack.append(q)
        if len(comp) != 4:
            continue
        r0 = min(r for r,c in comp); c0 = min(c for r,c in comp)
        shape = {(r-r0,c-c0) for r,c in comp}
        forms = {
            "up": {(0,0),(0,1),(0,2),(1,1)},
            "down": {(1,0),(1,1),(1,2),(0,1)},
            "left": {(0,0),(1,0),(2,0),(1,1)},
            "right": {(0,2),(1,2),(2,2),(1,1)},
        }
        for direction, form in forms.items():
            if shape == form:
                counts[direction] += 1
                break
    out = [[0] * 6 for _ in range(3)]
    # Two orientation-coded tracks, with repeated motifs represented in row 2.
    for i in range(min(counts["down"], 3)):
        out[0][2*i] = 3
    for i in range(min(counts["up"], 3)):
        out[0][3 + i] = 1
    if counts["down"] > 1:
        for i in range(min(counts["down"] - 1, 3)):
            out[2][2*i] = 3
    if counts["up"] > 1:
        for i in range(min(counts["up"] - 1, 3)):
            out[2][3 + i] = 1
    return out

